import {reconcile,LABELS,exportResults,toCSV,parseCSV,suggestMapping,normalizeReport,FIELDS} from './engine.mjs';
import {getDemo,sampleOrders,samplePayments} from './sample.mjs';
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v===null?'—':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:v%100?2:0,maximumFractionDigits:2}).format(v/100);
let data=getDemo(),result=reconcile(data.orders,data.payments),filter='all',reviewed=new Set(),detailId=null;
let isDemo=true,dirty=false,pendingImport=null,page=0;
let sources={orders:{name:'sample-orders.csv',loaded:true},payments:{name:'sample-payments.csv',loaded:true}};
function message(text,error=false){$('#message').textContent=text;$('#message').classList.toggle('error',error);$('#message').hidden=!text;}
function updateSources(){for(const kind of ['orders','payments'])$('#'+kind+'-meta').textContent=sources[kind].loaded?`${sources[kind].name} · ${data[kind].length} records`:'Waiting for your CSV report';
  $('#dataset-label').textContent=isDemo?'DEMO DATA':'YOUR REPORTS';$('#dataset-note').textContent=isDemo?'Explore a sample reconciliation, or import your own reports below.':'Reports stay in this browser. Import both files from the same reporting period.';
  document.body.classList.toggle('stale',dirty);$('#export-button').disabled=dirty;$('#run-button').disabled=!sources.orders.loaded||!sources.payments.loaded;
  $('#results-note').textContent=dirty?'Previous results — run reconciliation after both reports are ready.':'Open a record to inspect its payment trail.';
}
function download(name,content){const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function render(){const s=result.summary;
  $('#metrics').innerHTML=[['Order value',money(s.expected),`${s.orders} orders in your sales ledger`,'▤',''],['Captured payments',money(s.captured),`${s.payments} payment records · includes unmatched`,'⇄',''],['Matched orders',s.matched,`${s.orders?Math.round(s.matched/s.orders*100):0}% of orders fully reconciled`,'✓','green-text'],['Needs review',s.review,`${s.orphans} unmatched reference${s.orphans===1?'':'s'} included`,'!','orange-text']].map(([label,value,note,icon,color])=>`<article class="metric"><div class="metric-top">${label}<span class="metric-icon" aria-hidden="true">${icon}</span></div><div class="metric-value ${color}">${value}</div><div class="metric-note">${note}</div></article>`).join('');
  const percent=s.orders?Math.round(s.matched/s.orders*100):0;$('#match-heading').textContent=`${s.matched} of ${s.orders} orders matched`;$('#match-note').textContent='Your reconciliation at a glance';$('#progress-fill').style.width=`${percent}%`;$('#progress').setAttribute('aria-valuenow',percent);$('#match-percent').textContent=`${percent}%`;
  $('#result-count').textContent=result.rows.length;$('#review-count').textContent=s.review;
  $('#cash-breakdown').innerHTML=`<div class="cash-row"><span>Captured gross</span><strong>${money(s.captured)}</strong></div><div class="cash-row"><span>Refunds</span><strong>${s.refunds===null?'Incomplete':'− '+money(s.refunds)}</strong></div><div class="cash-row"><span>Gateway fees</span><strong>${s.fees===null?'Incomplete':'− '+money(s.fees)}</strong></div><div class="cash-total"><span>Net proceeds estimate</span><strong>${s.net===null?'Incomplete data':money(s.net)}</strong></div>`;
  const counts=Object.keys(LABELS).map(k=>[k,result.rows.filter(r=>r.issues.includes(k)).length]).filter(x=>x[1]);$('#issue-breakdown').innerHTML=counts.length?counts.map(([k,n])=>`<div class="issue-row"><span>${LABELS[k]}</span><strong>${n}</strong></div>`).join(''):'<p class="green-text">All records reconciled.</p>';
  renderRows();
}
function renderRows(){const query=$('#search').value.toLowerCase().trim();const rows=result.rows.filter(r=>(filter==='all'||(filter==='matched'?r.matched:!r.matched))&&[r.id,r.order?.customer,...r.payments.map(p=>p.id)].some(v=>String(v??'').toLowerCase().includes(query)));
  page=Math.min(page,Math.max(0,Math.ceil(rows.length/50)-1));const pageRows=rows.slice(page*50,page*50+50);
  $('#previous-page').disabled=page===0;$('#next-page').disabled=(page+1)*50>=rows.length;
  $('#result-rows').innerHTML=rows.length?pageRows.map(r=>`<tr><td><span class="order-id">${esc(r.id)}</span><span class="order-customer">${esc(r.order?.customer||(r.order?'Order record':'No matching order'))}</span></td><td>${money(r.order?.amount??null)}</td><td>${money(r.captured)}</td><td class="${r.difference?'orange-text':'muted'}">${r.difference>0?'+':''}${money(r.difference)}</td><td><span class="status ${r.matched?'matched':r.status==='pending'?'pending':r.status==='missing'?'missing':''}">${r.matched?'✓ Matched':esc(LABELS[r.status])}${r.issues.length>1?' +'+(r.issues.length-1):''}</span>${reviewed.has(r.id)?'<span class="reviewed-label">Reviewed</span>':''}</td><td><button class="row-button" data-detail="${esc(r.id)}" aria-label="View ${esc(r.id)} details">↗</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No results match this view.</td></tr>';$('#visible-count').textContent=`Showing ${rows.length?page*50+1:0}–${Math.min((page+1)*50,rows.length)} of ${rows.length} records`;
}
function run(){if(!sources.orders.loaded||!sources.payments.loaded)throw Error('Import both reports before reconciling.');const next=reconcile(data.orders,data.payments);result=next;dirty=false;page=0;reviewed.clear();$('#detail-dialog').close();render();updateSources();message(`Reconciliation complete. ${result.summary.matched} orders matched; ${result.summary.review} records need review.`);return result.summary;}
$('#run-button').addEventListener('click',()=>{try{run();}catch(error){message(error.message,true);}});
$('#demo-button').addEventListener('click',()=>{data=getDemo();isDemo=true;dirty=false;page=0;sources={orders:{name:'sample-orders.csv',loaded:true},payments:{name:'sample-payments.csv',loaded:true}};reviewed.clear();result=reconcile(data.orders,data.payments);filter='all';$('#search').value='';document.querySelectorAll('[data-filter]').forEach(x=>{const active=x.dataset.filter==='all';x.classList.toggle('selected',active);x.setAttribute('aria-pressed',String(active));});render();updateSources();message('Sample reports restored.');});
$('#export-button').addEventListener('click',()=>{if(dirty){message('Run reconciliation before exporting.',true);return;}download('paymatch-reconciliation.csv',exportResults(result,reviewed));message('Reconciliation CSV exported with all records and review annotations.');});
$('#templates-button').addEventListener('click',()=>$('#templates-dialog').showModal());
$('#download-orders').addEventListener('click',()=>download('sample-orders.csv',toCSV(sampleOrders)));
$('#download-payments').addEventListener('click',()=>download('sample-payments.csv',toCSV(samplePayments)));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;page=0;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});renderRows();}));$('#search').addEventListener('input',()=>{page=0;renderRows();});
$('#previous-page').addEventListener('click',()=>{page=Math.max(0,page-1);renderRows();});
$('#next-page').addEventListener('click',()=>{page++;renderRows();});
for(const kind of ['orders','payments']){
  $('#'+kind+'-upload').addEventListener('click',()=>$('#'+kind+'-file').click());
  $('#'+kind+'-file').addEventListener('change',async e=>{
    const file=e.target.files[0];if(!file)return;const button=$('#'+kind+'-upload');button.disabled=true;
    try{if(!/\.csv$/i.test(file.name))throw Error('Choose a UTF-8 CSV file.');if(file.size>5*1024*1024)throw Error('File is larger than 5 MB.');
      let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());}catch{throw Error('Save this report as UTF-8 CSV and try again.');}
      const parsed=parseCSV(text);const mapping=suggestMapping(parsed.headers,kind);pendingImport={kind,parsed,name:file.name};
      $('#import-title').textContent=kind==='orders'?'Map your order columns':'Map your payment columns';$('#import-description').textContent=`${file.name} · ${parsed.rows.length} records found`;
      $('#mapping-fields').innerHTML=FIELDS[kind].map(([key,label,required])=>`<label>${label}${required?' *':''}<select name="${key}" aria-label="${label}" ${required?'required':''}><option value="" ${mapping[key]<0?'selected':''}>${required?'Choose a column':'Not in this report'}</option>${parsed.headers.map((h,i)=>`<option value="${i}" ${mapping[key]===i?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`).join('');
      $('#mapping-note').textContent=kind==='orders'?'Blank expected refunds mean unknown. If no refund is expected, enter 0 in your report. Currency must be INR when mapped.':'Map gross captured amounts, not net settlement amounts. Blank refunds or fees are unknown and flag incomplete data. Use 0 when none apply. Accepted statuses: captured, paid, success, successful, succeeded, completed, settled, refunded, partially_refunded, pending, authorized, authorised, processing, created, failed, cancelled, canceled, declined. Other statuses are flagged for review.';
      $('#import-error').hidden=true;$('#import-dialog').showModal();
    }catch(error){message(error.message,true);}finally{button.disabled=false;e.target.value='';}
  });
}
$('#import-form').addEventListener('submit',e=>{e.preventDefault();if(!pendingImport)return;try{
  const {kind,parsed,name}=pendingImport;const form=new FormData(e.target);const mapping=Object.fromEntries(FIELDS[kind].map(([key])=>[key,form.get(key)===''?-1:Number(form.get(key))]));
  const rows=normalizeReport(parsed,kind,mapping);
  // Commit the whole validated report at once. A failed import never replaces existing data.
  if(isDemo){data={orders:[],payments:[]};sources={orders:{name:'',loaded:false},payments:{name:'',loaded:false}};isDemo=false;}
  data[kind]=rows;sources[kind]={name,loaded:true};dirty=true;reviewed.clear();updateSources();
  message(`${rows.length} ${kind} imported. ${sources.orders.loaded&&sources.payments.loaded?'Both reports are ready. Run reconciliation to update the results.':'Import your other report to continue.'}`);$('#import-dialog').close();pendingImport=null;
}catch(error){$('#import-error').textContent=error.message;$('#import-error').hidden=false;}});
document.querySelectorAll('.close-dialog').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
$('#import-dialog').addEventListener('close',()=>{pendingImport=null;});
function issueDescription(r,key){switch(key){case 'orphan':return 'No order in this report has the exact reference shown on this payment.';case 'missing':return 'No captured payment was found for this order.';case 'amount':return r.difference<0?`Captured amount is ${money(-r.difference)} below the order amount.`:`Captured amount is ${money(r.difference)} above the order amount.`;case 'refund':return `Expected refund: ${money(r.order.refund)}. Reported refund: ${money(r.refund)}.`;case 'refund_review':return 'The order ledger does not specify the expected refund. Supply an amount, or 0 if none is expected.';case 'pending':return `${r.pendingCount} pending or authorized payment(s) excluded from captured gross.`;case 'unknown':return 'An unrecognized payment status needs review. Its amount is excluded from captured gross.';case 'incomplete':return 'Missing fee or refund values prevent a complete comparison. Enter 0 in your report when none apply.';default:return LABELS[key];}}
function showDetail(id){if(dirty)throw Error('Run reconciliation before reviewing updated reports.');const r=result.rows.find(x=>x.id===id);if(!r)throw Error('Record not found.');detailId=id;$('#detail-title').textContent=id;
  $('#detail-content').innerHTML=`<p class="muted">${esc(r.order?.customer||'No customer supplied')}${r.order?.date?' · '+esc(r.order.date):''}</p><div class="detail-summary"><div><span>Order amount</span><strong>${money(r.order?.amount??null)}</strong></div><div><span>Captured gross</span><strong>${money(r.captured)}</strong></div><div><span>Difference</span><strong class="${r.difference?'orange-text':''}">${r.difference>0?'+':''}${money(r.difference)}</strong></div></div>${r.issues.length?`<div class="detail-issues">${r.issues.map(k=>`<strong>${LABELS[k]}</strong> · ${esc(issueDescription(r,k))}`).join('\n')}</div>`:'<div class="message">✓ Gross payment and known refunds match. No unresolved payment status.</div>'}<h3 class="detail-title">Payment records (${r.payments.length})</h3>${r.payments.length?r.payments.map(p=>`<div class="detail-payment"><div><strong>${esc(p.id)}</strong><strong>${money(p.amount)}</strong></div><div><span>${esc(p.rawStatus)}</span><span>${esc(p.date)}</span></div><p>${p.status==='captured'?'Included in captured gross':'Excluded from captured gross'} · Refund ${p.refund===null?'unknown':money(p.refund)} · Fee ${p.fee===null?'unknown':money(p.fee)}</p></div>`).join(''):'<p class="muted">No payment records for this order.</p>'}<h3 class="detail-title">Net proceeds estimate</h3><p>${money(r.captured)} − ${money(r.refund)} refunds − ${money(r.fees)} fees = <strong>${r.net===null?'Incomplete data':money(r.net)}</strong></p><p class="footnote">${r.failedCount?`${r.failedCount} failed payment(s) excluded from captured amounts. Any reported fees are included. `:''}Review marks are session notes; they do not resolve discrepancies or change amounts.</p>`;
  $('#review-button').hidden=r.matched;$('#review-button').textContent=reviewed.has(id)?'Undo reviewed':'Mark reviewed';if(!$('#detail-dialog').open)$('#detail-dialog').showModal();return {order_id:id,issues:r.issues,reviewed:reviewed.has(id)};
}
$('#result-rows').addEventListener('click',e=>{const button=e.target.closest('[data-detail]');if(button)try{showDetail(button.dataset.detail);}catch(error){message(error.message,true);}});
$('#review-button').addEventListener('click',()=>{if(!detailId||dirty)return;if(reviewed.has(detailId))reviewed.delete(detailId);else reviewed.add(detailId);renderRows();showDetail(detailId);});
render();updateSources();

// Tools share the same session, calculations, and visible actions as the app.
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
  const validateEmpty=input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('Expected an empty object.');};
  register({name:'read_reconciliation_summary',title:'Read reconciliation summary',description:'Read totals from the current completed reconciliation. Fails if imported reports have changed and need a new run. All amounts are integer INR paise.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){validateEmpty(input);if(dirty)throw Error('Reports changed. Run reconciliation first.');return {...result.summary,currency:'INR',unit:'paise',demo:isDemo};}});
  register({name:'run_reconciliation',title:'Reconcile loaded reports',description:'Compare both loaded reports and update the visible results. Clears prior review annotations.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){validateEmpty(input);return {...run(),currency:'INR',unit:'paise'};}});
  register({name:'open_reconciliation_record',title:'Open payment trail',description:'Open the visible details for an exact order reference in the completed results.',inputSchema:{type:'object',properties:{order_id:{type:'string',minLength:1}},required:['order_id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.order_id!=='string'||!input.order_id||Object.keys(input).some(k=>k!=='order_id'))throw Error('Provide an exact order_id.');return showDetail(input.order_id);}});
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
